    nc=nc+1; if(a_isa_ring!==b_isa_ring)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=isa_ring cyc=%0d",cyc); end
    nc=nc+1; if(a_isa_lp_data!==b_isa_lp_data)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=isa_lp_data cyc=%0d",cyc); end
    nc=nc+1; if(a_ag_v!==b_ag_v)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=ag_v cyc=%0d",cyc); end
    nc=nc+1; if(a_ag_src!==b_ag_src)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=ag_src cyc=%0d",cyc); end
    nc=nc+1; if(a_ag_tag!==b_ag_tag)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=ag_tag cyc=%0d",cyc); end
    nc=nc+1; if(a_ag_d!==b_ag_d)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=ag_d cyc=%0d",cyc); end
    nc=nc+1; if(a_vm_rq!==b_vm_rq)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=vm_rq cyc=%0d",cyc); end
    nc=nc+1; if(a_vm_kq!==b_vm_kq)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=vm_kq cyc=%0d",cyc); end
    nc=nc+1; if(a_fault!==b_fault)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=fault cyc=%0d",cyc); end
    nc=nc+1; if(a_fault_cause!==b_fault_cause)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=fault_cause cyc=%0d",cyc); end
    nc=nc+1; if(a_done!==b_done)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=done cyc=%0d",cyc); end
    nc=nc+1; if(a_stat_cycles!==b_stat_cycles)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=stat_cycles cyc=%0d",cyc); end
   end end
  if(bad==0)$display("LPF_EQ PASS compared=%0d",nc); else $display("LPF_EQ FAIL mismatches=%0d of %0d",bad,nc);
  $finish; end
endmodule
